import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.doxMM-x8.js";const k=JSON.parse('{"title":"Quick start","description":"","frontmatter":{"docLocale":"en","counterpart":"/getting-started/quickstart","contentType":"guide","prev":{"text":"Project documentation","link":"/en/docs/"},"next":{"text":"Lab and asset library","link":"/en/guides/lab-viewer"}},"headers":[],"relativePath":"en/getting-started/quickstart.md","filePath":"en/getting-started/quickstart.md"}'),n={name:"en/getting-started/quickstart.md"};function r(o,e,p,l,d,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h1><p>Start the Node service and Web application, create an account and open a persistent Lab. Use Linux or Windows with <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/.node-version" target="_blank" rel="noreferrer">Node 24.18.0</a> and <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/package.json" target="_blank" rel="noreferrer">pnpm 11.17.0</a>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/CaiZongyuan/labworld.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labworld</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Run commands from the repository root. The service initializes its embedded database and recovery before accepting HTTP. It listens at <code>http://127.0.0.1:3000</code>; Web opens at <code>http://127.0.0.1:5173</code>. Data stays in <code>data/</code> across restarts. The startup output names the owned development-process ledger.</p><h2 id="open-the-application" tabindex="-1">Open the application <a class="header-anchor" href="#open-the-application" aria-label="Permalink to &quot;Open the application&quot;">​</a></h2><ol><li>Open <a href="http://127.0.0.1:5173/register" target="_blank" rel="noreferrer">http://127.0.0.1:5173/register</a> and register with a password of 12–128 characters. The first account is Owner; later accounts are Members.</li><li>Login and registration open Lab. Create a Lab, then open its space.</li><li>Open Assets, upload a GLB with source, license and version, and wait for validation. The previous valid model stays available after a rejected import.</li><li>Register an Entity and place its Scene Node in the Lab. Save the layout and refresh; the same Lab and selected Entity can be opened through the address.</li><li>Continue with the <a href="./../guides/lab-viewer">Lab guide</a>, <a href="./../guides/server-world">World</a> and <a href="./../guides/server-devices">Devices</a>. Users and Agents share the retained API and backend device programs.</li></ol><p>The shared home remains at <code>/</code>. Settings and API-key links work at <code>/settings</code> and <code>/api-keys</code>. Removed-module bookmarks show an unavailable page with a way home.</p><h2 id="verify-and-stop" tabindex="-1">Verify and stop <a class="header-anchor" href="#verify-and-stop" aria-label="Permalink to &quot;Verify and stop&quot;">​</a></h2><p>Keep development running and use another terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/live</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/v1/system/status</span></span></code></pre></div><p>Ready responses return HTTP 200 with <code>x-request-id</code>; system status reports the applied schema. Press Ctrl+C in the development terminal to drain and stop both processes. Persistent data remains. After an abnormal supervisor exit, use the printed ledger with <code>pnpm dev:recover &lt;ledger&gt;</code> before restarting. Preserve active services and unknown data.</p><p>Copy <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/.env.example" target="_blank" rel="noreferrer">.env.example</a> to an untracked <code>.env</code> to change Node and Web settings. Node entry commands load that file and Vite reads it from the repository root. See <a href="./../reference/config">generated configuration</a> and <a href="./../guides/server-foundation">separate directories and ports</a>.</p><p>For stopped-service backup, restore into a new or empty directory and password recovery, follow <a href="./../guides/server-operations">server operations</a>. A forgotten password uses the operator CLI.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts:check</span></span></code></pre></div><p>See <a href="./../testing/feedback-loop">development and validation</a> for browser checks and complete coverage.</p><hr><p>Source version：<code>2fef28c35afe</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/2fef28c35afea44ae2018f0e4b6a3a18a96a2bf7/docs/getting-started/quickstart.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,17)])])}const g=a(n,[["render",r]]);export{k as __pageData,g as default};
